        title = LocalizedText("""Novena a la Sagrada Familia""", """Holy Family Novena""", """Novena à Sagrada Família"""),
        patron = LocalizedText("""Santo patrón de las familias santas""", """Patron saint of for holy families""", """Novena à Sagrada Família"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""La Sagrada Familia de Jesús, María y José es para toda familia una inspiración y un modelo a seguir.""", """The Holy Family of Jesus, Mary, and Joseph provides every family an inspiration and model to follow.""", """A Sagrada Família de Jesus, Maria e José oferece a toda família uma inspiração e um modelo a seguir."""),
        miraculousHistory = LocalizedText("", "", ""),
